import pandas as pd
for fid in ['FARM_A', 'FARM_T', 'FARM_AB', 'FARM_AD', 'FARM_AF', 'FARM_AH', 'FARM_B', 'FARM_C', 'FARM_F', 'FARM_G', 'FARM_J', 'FARM_K', 'FARM_N', 'FARM_P', 'FARM_R', 'FARM_U', 'FARM_W', 'FARM_Y', 'FARM_Z']:
    file = f'/app/dataset/production_{fid}.csv'
    try:
        with open(file, 'rb') as f: raw = f.read(100)
        enc = 'utf-16' if raw.startswith(b'\xff\xfe') else 'utf-8'
        with open(file, 'r', encoding=enc) as f:
            for _ in range(3): f.readline()
            sep = ';' if ';' in f.readline() else ','
        df = pd.read_csv(file, skiprows=3, encoding=enc, sep=sep, on_bad_lines='skip')
        ts_col = [c for c in df.columns if 'timestamp' in c.lower()][0]
        val_cols = [c for c in df.columns if '888888' in str(df[c].values)]
        if not val_cols:
            for c in df.columns:
                try:
                    if (pd.to_numeric(df[c], errors='coerce') > 800000).any():
                        val_cols.append(c)
                except: pass
        if val_cols:
            col = val_cols[0]
            dups = df[df.duplicated(subset=[ts_col], keep=False)].sort_values(ts_col)
            # check if 'last' is not 888888.8
            last_vals = df.drop_duplicates(subset=[ts_col], keep='last')[col]
            has_888_last = (pd.to_numeric(last_vals, errors='coerce') > 800000).any()
            print(f"{fid}: keep='last' has 888888? {has_888_last}")
    except Exception as e:
        pass
EOF
